window.VO = [{"id":"n01","text":"You're the passport officer, and one of these five men is flying on someone else's passport.","at":0.24,"t0":0.12,"t1":5.1},{"id":"n02","text":"Whoever you stop will miss his flight.","at":10.9,"t0":5.45,"t1":7.29},{"id":"n03","text":"So who do you stop?","at":16.4,"t0":8.2,"t1":9.355},{"id":"n04","text":"Were you that sure?","at":28.11,"t0":14.055,"t1":15.055},{"id":"n05","text":"Because in a real test, trained passport officers waved through one lookalike in seven.","at":31.61,"t0":15.805,"t1":20.655},{"id":"n06","text":"Number two is going home for the first time in nine years, and his photo's from the year he left.","at":42.71,"t0":21.355,"t1":26.805},{"id":"n07","text":"If you stopped him, he's in a back room now, holding his own passport.","at":55.01,"t0":27.505,"t1":31.215},{"id":"m08a","text":"That's me.","at":63.63,"t0":31.815,"t1":32.68},{"id":"m08b","text":"I just got old.","at":66.28,"t0":33.14,"t1":34.36},{"id":"n09","text":"So who was it?","at":69.92,"t0":34.96,"t1":35.96},{"id":"n10","text":"Number four matched his photo almost perfectly, but it isn't his.","at":73.92,"t0":36.96,"t1":40.635},{"id":"n11","text":"It's his brother's.","at":82.17,"t0":41.085,"t1":42.185},{"id":"n12","text":"Unless you stopped him, he's boarding now, as his brother.","at":86.17,"t0":43.085,"t1":46.17},{"id":"n13","text":"Now look again.","at":94.94,"t0":47.47,"t1":48.45},{"id":"n14","text":"What gave him away?","at":98.34,"t0":49.17,"t1":50.29}];
